/**
 * The Night Wrestling
 * -------------------
 * Jacob wrestles a man by the Jabbok until daybreak, and his hip is touched; he is named Israel, for he strove with God. Stage: a riverbank in the dark before dawn, two figures locked, a hip given way, a name changed at sunrise; the first red light on the water.
 *
 * Palette 0x1a0e08 → 0x060402 · light: dusk · hero: water
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jacob-kit.js.
 */

import { THREE, createScene, water, rock, person } from './jacob-kit.js';

const BG = 0x1a0e08;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2099830388, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* river: animated water between grassy banks */
    water(W, group, 260, 26, -0.4, 0x020101, 0x070502);
    W.ground(260, 95, 0, 60, 0x060402, { amp: 0.5, j: 0.3, flat: 24, fz: 54 });
    W.ground(260, 95, 0, -64, 0x050302, { amp: 0.6, j: 0.3, flat: 24, fz: -58 });
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x030201), [0, -0.05, 12.6]);
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x030201), [0, -0.05, -14.6]);

    /* hero: the water — a focal stone in the flow */
    rock(W, group, 0, 0, 11, 1.7, 0x050402);

    /* figures */
    person(W, group, [-5, 0, 16], { robe: 0x1a0e08, ry: 0.11, s: 1.16 });
    person(W, group, [4.5, 0, 17], { robe: 0x060402, ry: -0.63, s: 1.03 });
    person(W, group, [1, 0, 6], { robe: 0x8a6a44, ry: 0.30, s: 1.08 });

    return W.finish();
}

export default { build };
